insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('kp-02', 'k-percent', 1, 'لاحظ معلم أن 4% من طلابه البالغ عددهم 150 طالباً تأخروا عن الطابور الصباحي. كم عدد الطلاب المتأخرين؟', '["4","6","8","10"]'::jsonb, 1, '150 × 4 ÷ 100 = 6 طلاب. (1% من 150 = 1.5، فيكون 4% = 1.5 × 4 = 6).') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('kp-03', 'k-percent', 1, 'أعدّ معلم اختباراً درجته الكلية 60 درجة، وخصص 20% منها لأسئلة التفكير العليا. كم درجة خصصت لهذه الأسئلة؟', '["10","12","15","18"]'::jsonb, 1, '20% تعني الخُمس، و60 ÷ 5 = 12 درجة.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('kp-04', 'k-percent', 1, 'أنهى 12 طالباً من أصل 48 طالباً حفظ السورة المقررة في الأسبوع الأول. ما النسبة المئوية لمن أنهوا الحفظ؟', '["20%","25%","30%","35%"]'::jsonb, 1, 'النسبة = (الجزء ÷ الكل) × 100 = (12 ÷ 48) × 100 = 25%. لاحظ أن 12 هي ربع 48.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('kp-05', 'k-percent', 1, 'حصلت طالبة على 54 درجة من أصل 60 في اختبار العلوم. ما النسبة المئوية لدرجتها؟', '["80%","85%","88%","90%"]'::jsonb, 3, '(54 ÷ 60) × 100 = 90%. (54/60 = 9/10 = 90%).') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('kp-06', 'k-percent', 2, 'كان سعر جهاز عرض تعليمي 1200 ريال، وخُفّض سعره بنسبة 15%. كم أصبح سعره بعد التخفيض؟', '["1020 ريالاً","1050 ريالاً","1080 ريالاً","1140 ريالاً"]'::jsonb, 0, 'قيمة الخصم = 1200 × 15% = 180 ريالاً، فيصبح السعر 1200 − 180 = 1020 ريالاً. (أو مباشرة: 1200 × 0.85 = 1020).') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('kp-07', 'k-percent', 2, 'ارتفع عدد المسجلين في نشاط القراءة من 80 طالباً إلى 92 طالباً. ما نسبة الزيادة؟', '["12%","13%","15%","20%"]'::jsonb, 2, 'نسبة التغير = (مقدار التغير ÷ القيمة الأصلية) × 100 = (12 ÷ 80) × 100 = 15%. القسمة دائماً على القيمة قبل التغير.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('kp-08', 'k-percent', 2, 'ينظم طالب وقته فيذاكر 4 ساعات يومياً، ويخصص 15% منها للمراجعة. كم دقيقة يقضيها في المراجعة يومياً؟', '["24 دقيقة","30 دقيقة","36 دقيقة","40 دقيقة"]'::jsonb, 2, '4 ساعات = 240 دقيقة، و240 × 15% = 36 دقيقة.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('kp-09', 'k-percent', 2, 'ادّخر رجل 12000 ريال حال عليها الحول وبلغت النصاب. كم ريالاً يخرج زكاةً لها؟', '["250 ريالاً","275 ريالاً","300 ريالاً","325 ريالاً"]'::jsonb, 2, 'الزكاة ربع العشر = 2.5%، أي 12000 ÷ 40 = 300 ريال.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('kp-10', 'k-percent', 2, 'خصصت مدرسة 7.5% من ميزانيتها البالغة 400,000 ريال لتجهيز مصادر التعلم. كم ريالاً خُصص لذلك؟', '["22,500","25,000","30,000","35,000"]'::jsonb, 2, '400,000 × 7.5 ÷ 100 = 30,000 ريال. (10% = 40,000 ونصفها 5% = 20,000 و2.5% = 10,000، فيكون 7.5% = 30,000).') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('kp-11', 'k-percent', 2, 'في صف يضم 50 طالباً، شارك 40% منهم في مسابقة ثقافية، وتأهل 30% من المشاركين للتصفيات النهائية. كم طالباً تأهل؟', '["6","8","10","15"]'::jsonb, 0, 'المشاركون = 50 × 0.4 = 20 طالباً، والمتأهلون = 20 × 0.3 = 6 طلاب. النسب المتتالية تضرب تتابعاً.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('kp-12', 'k-percent', 3, 'في مدرسة 400 طالب، زاد عددهم بنسبة 10% في العام التالي، ثم نقص بنسبة 10% في العام الذي يليه. كم عدد الطلاب في نهاية العامين؟', '["396","400","404","440"]'::jsonb, 0, 'بعد الزيادة: 400 × 1.1 = 440، وبعد النقص: 440 × 0.9 = 396. لا تعود القيمة الأصلية لأن النقص حُسب من عدد أكبر.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('kp-13', 'k-percent', 3, 'في مكتبة صفية 80 كتاباً، 30% منها كتب علمية. أضيف إليها 20 كتاباً جديداً منها 16 كتاباً علمياً. ما نسبة الكتب العلمية بعد الإضافة؟', '["36%","40%","44%","48%"]'::jsonb, 1, 'العلمية أولاً = 80 × 0.3 = 24، وبعد الإضافة = 24 + 16 = 40 من أصل 100 كتاب، فالنسبة = 40%.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('kp-14', 'k-percent', 2, 'أعلنت معلمة أن 85% من طالبات صفها البالغ عددهن 40 طالبة سلّمن المشروع في موعده. كم طالبة لم تسلّم المشروع في الموعد؟', '["4","6","8","34"]'::jsonb, 1, 'من لم يسلمن = 15% من 40 = 6 طالبات. انتبه: السؤال عن غير المسلمات لا المسلمات.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('kp-15', 'k-percent', 3, 'اشترى تاجر حاسوباً بـ 2000 ريال وباعه بربح نسبته 20%، ثم عاد المشتري وباعه بخسارة 10% من سعر شرائه. بكم باعه المشتري الثاني؟', '["2100 ريال","2160 ريالاً","2200 ريال","2400 ريال"]'::jsonb, 1, 'سعر البيع الأول = 2000 × 1.2 = 2400، والبيع الثاني = 2400 × 0.9 = 2160 ريالاً.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('kp-16', 'k-percent', 2, 'في استطلاع شارك فيه 1500 طالب، أفاد 0.4% منهم بعدم استخدام المنصة التعليمية إطلاقاً. كم عددهم؟', '["4","6","40","60"]'::jsonb, 1, '1500 × 0.4 ÷ 100 = 6 طلاب. انتبه للفاصلة العشرية: 0.4% وليست 4%.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('kr-01', 'k-ratio', 1, 'يصحح معلم 6 أوراق اختبار في 15 دقيقة. كم ورقة يصحح في 45 دقيقة بنفس المعدل؟', '["12","15","18","24"]'::jsonb, 2, 'الزمن تضاعف 3 مرات (45 ÷ 15 = 3)، فالأوراق = 6 × 3 = 18 ورقة. تناسب طردي.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('kr-02', 'k-ratio', 1, 'إذا كان يُخصص معلم واحد لكل 8 طلاب في رحلة مدرسية، فكم معلماً يلزم لـ 56 طالباً؟', '["6","7","8","9"]'::jsonb, 1, '56 ÷ 8 = 7 معلمين.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('kr-03', 'k-ratio', 2, 'تكتب طالبة 3 صفحات من بحثها كل 20 دقيقة. كم صفحة تنجز في ساعة وثلث؟', '["9","10","12","15"]'::jsonb, 2, 'ساعة وثلث = 80 دقيقة = 4 × 20 دقيقة، فالصفحات = 3 × 4 = 12 صفحة.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('kr-04', 'k-ratio', 2, 'صممت معلمة ركناً تعليمياً يحتاج 1.5 متر من القماش لكل صف. كم متراً تحتاج لتجهيز 12 صفاً؟', '["15","16","18","20"]'::jsonb, 2, '1.5 × 12 = 18 متراً.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('kr-05', 'k-ratio', 2, 'إذا كان مقياس الرسم في خريطة 1 : 40 كم، وكانت المسافة بين مدينتين على الخريطة 3.5 سم، فكم المسافة الحقيقية بينهما؟', '["120 كم","140 كم","160 كم","180 كم"]'::jsonb, 1, 'المسافة الحقيقية = 3.5 × 40 = 140 كم.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('kr-06', 'k-ratio', 2, 'ركض سالم 900 متر في 5 دقائق، وركض بدر 640 متراً في 4 دقائق. أيهما أسرع؟', '["سالم أسرع","بدر أسرع","سرعتاهما متساويتان","لا يمكن المقارنة"]'::jsonb, 0, 'معدل سالم = 900 ÷ 5 = 180 م/د، ومعدل بدر = 640 ÷ 4 = 160 م/د، فسالم أسرع.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('kr-07', 'k-ratio', 2, 'يبعد مسجد الحي عن منزل أحمد 900 متر، ويمشي بسرعة 5 أمتار في الثانية. كم دقيقة يستغرق للوصول؟', '["دقيقتان","3 دقائق","4 دقائق","5 دقائق"]'::jsonb, 1, 'الزمن = المسافة ÷ السرعة = 900 ÷ 5 = 180 ثانية = 3 دقائق.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('kr-08', 'k-ratio', 3, 'وزعت معلمة زمن حصة نشاط مدته 45 دقيقة بين قراءة ونقاش وتطبيق بنسبة 4 : 3 : 2. كم دقيقة خُصصت للنقاش؟', '["10 دقائق","15 دقيقة","20 دقيقة","25 دقيقة"]'::jsonb, 1, 'مجموع الأجزاء = 4 + 3 + 2 = 9، وقيمة الجزء = 45 ÷ 9 = 5 دقائق، فالنقاش = 3 × 5 = 15 دقيقة.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('kr-09', 'k-ratio', 3, 'قرأ طالب 12 صفحة من قصة تقع في 30 صفحة خلال 24 دقيقة. إذا استمر بالسرعة نفسها، فكم دقيقة يحتاج لإنهاء ما تبقى؟', '["30 دقيقة","36 دقيقة","40 دقيقة","48 دقيقة"]'::jsonb, 1, 'معدل القراءة = 24 ÷ 12 = دقيقتان للصفحة، والمتبقي = 30 − 12 = 18 صفحة × 2 = 36 دقيقة.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('kr-10', 'k-ratio', 3, 'ينجز 3 عمال دهان قاعة مدرسية في 12 يوماً. كم يوماً يحتاج 9 عمال لإنجاز العمل نفسه بالكفاءة نفسها؟', '["3 أيام","4 أيام","6 أيام","36 يوماً"]'::jsonb, 1, 'تناسب عكسي: العمل الكلي = 3 × 12 = 36 يوم عمل، وعدد الأيام = 36 ÷ 9 = 4 أيام.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('kr-11', 'k-ratio', 2, 'يملأ أنبوب واحد خزاناً في 48 دقيقة. إذا فُتح أربعة أنابيب مماثلة معاً، فكم دقيقة يلزم لملء الخزان؟', '["8 دقائق","12 دقيقة","16 دقيقة","24 دقيقة"]'::jsonb, 1, 'تناسب عكسي: 48 ÷ 4 = 12 دقيقة.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('kr-12', 'k-ratio', 3, 'في مدرسة، يوجد معلم لكل 6 طلاب، ويخصص لكل طالب 3 كتب. إذا كان في المدرسة 15 معلماً، فكم كتاباً تحتاج المدرسة؟', '["180","240","270","300"]'::jsonb, 2, 'عدد الطلاب = 15 × 6 = 90 طالباً، وعدد الكتب = 90 × 3 = 270 كتاباً.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('kr-13', 'k-ratio', 2, 'سيارة تقطع 240 كم في 3 ساعات. ما سرعتها المتوسطة؟', '["60 كم/س","70 كم/س","80 كم/س","90 كم/س"]'::jsonb, 2, 'السرعة = المسافة ÷ الزمن = 240 ÷ 3 = 80 كم/س.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('kr-14', 'k-ratio', 3, 'إذا كان 5 أقلام تكفي 3 طلاب في نشاط فني، فكم قلماً يلزم لـ 24 طالباً بالنسبة نفسها؟', '["30","35","40","45"]'::jsonb, 2, '24 ÷ 3 = 8 مجموعات، فالأقلام = 5 × 8 = 40 قلماً. (أو بالضرب التبادلي: س = 24 × 5 ÷ 3 = 40).') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('kn-01', 'k-numbers', 1, 'أي المجموعات الآتية جميع أعدادها أولية؟', '["2، 9، 13","3، 11، 21","5، 17، 23","7، 15، 19"]'::jsonb, 2, '5 و17 و23 كلها أولية. أما 9 = 3×3، و21 = 3×7، و15 = 3×5 فليست أولية.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('kn-02', 'k-numbers', 1, 'ما التحليل الصحيح للعدد 48 إلى عوامله الأولية؟', '["2³ × 3","2⁴ × 3","2² × 3²","2³ × 3²"]'::jsonb, 1, '48 = 16 × 3 = 2⁴ × 3. تحقق: 2×2×2×2×3 = 48.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('kn-03', 'k-numbers', 2, 'أي الأعداد الآتية ليس أولياً؟', '["31","41","51","61"]'::jsonb, 2, '51 = 3 × 17 (مجموع رقميه 5+1 = 6 يقبل القسمة على 3). الأعداد 31 و41 و61 أولية.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('kn-04', 'k-numbers', 2, 'أي من الأعداد الآتية لا يشترك مع العدد 42 في أي عامل أولي؟', '["12","25","14","21"]'::jsonb, 1, '42 = 2 × 3 × 7، بينما 25 = 5 × 5 فلا عامل مشتركاً بينهما. أما 12 (يشترك في 2 و3) و14 (2 و7) و21 (3 و7).') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('kn-05', 'k-numbers', 1, 'أي الأعداد الآتية يُعد من القواسم المشتركة للعددين 36 و54؟', '["4","8","9","12"]'::jsonb, 2, '9 يقسم 36 (=9×4) ويقسم 54 (=9×6). أما 4 و8 و12 فلا تقسم 54.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('kn-06', 'k-numbers', 2, 'ما القاسم المشترك الأكبر للعددين 24 و40؟', '["4","6","8","12"]'::jsonb, 2, '24 = 2³×3، و40 = 2³×5، والمشترك بأصغر أس = 2³ = 8.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('kn-07', 'k-numbers', 3, 'يريد معلم توزيع 48 قلماً و72 كراسة على أكبر عدد ممكن من الطلاب بالتساوي دون أن يتبقى شيء. كم طالباً يمكن التوزيع عليهم؟', '["12","16","24","36"]'::jsonb, 2, 'المطلوب ق.م.أ (48، 72): 48 = 2⁴×3 و72 = 2³×3²، فالقاسم المشترك الأكبر = 2³×3 = 24 طالباً.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('kn-08', 'k-numbers', 2, 'ما القاسم المشترك الأكبر للأعداد 20 و30 و50؟', '["5","10","15","20"]'::jsonb, 1, '10 يقسم الثلاثة جميعاً، ولا يوجد أكبر منه يقسمها (20 لا يقسم 30 و50 لا تقبل 15).') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('kn-09', 'k-numbers', 1, 'أي الأعداد الآتية من مضاعفات العدد 7؟', '["27","36","42","52"]'::jsonb, 2, '42 = 7 × 6. الباقي ليست من مضاعفات 7.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('kn-10', 'k-numbers', 2, 'ما المضاعف المشترك الأصغر للعددين 6 و10؟', '["16","30","60","120"]'::jsonb, 1, '6 = 2×3 و10 = 2×5، وم.م.أ = 2×3×5 = 30 (كل العوامل بأكبر أس).') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('kn-11', 'k-numbers', 3, 'تنطلق حافلتان من المدرسة معاً في الساعة 6:30 صباحاً؛ الأولى كل 15 دقيقة والثانية كل 20 دقيقة. متى تنطلقان معاً مرة أخرى لأول مرة؟', '["7:00","7:10","7:30","7:35"]'::jsonb, 2, 'م.م.أ (15، 20) = 60 دقيقة، فتلتقيان بعد ساعة: 6:30 + 1:00 = 7:30.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('kn-12', 'k-numbers', 3, 'تقام ثلاثة أنشطة دورية في مدرسة: الإذاعي كل 3 أيام، والرياضي كل 4 أيام، والعلمي كل 6 أيام. إذا أقيمت جميعها اليوم، فبعد كم يوم تقام معاً مرة أخرى؟', '["اليوم 8","اليوم 12","اليوم 18","اليوم 24"]'::jsonb, 1, 'م.م.أ (3، 4، 6) = 12 يوماً.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('kn-13', 'k-numbers', 2, 'عدد طلاب ثلاثة صفوف: 24 و36 و48 طالباً. يراد تقسيم طلاب كل صف إلى فرق متساوية العدد في الصفوف الثلاثة دون بقاء أحد. ما أكبر عدد ممكن من الطلاب في الفريق الواحد؟', '["6","8","12","24"]'::jsonb, 2, 'ق.م.أ (24، 36، 48) = 12: فيقسم الأول لفريقين والثاني لثلاثة والثالث لأربعة.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('kn-14', 'k-numbers', 1, 'أي العبارات الآتية صحيحة؟', '["العدد 1 عدد أولي","العدد 2 هو العدد الزوجي الأولي الوحيد","كل الأعداد الفردية أولية","العدد 0 عدد أولي"]'::jsonb, 1, '2 هو الزوجي الأولي الوحيد. أما 1 و0 فليسا أوليين ولا مؤلفين، وليست كل الأعداد الفردية أولية (مثل 9 و15).') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('kg-01', 'k-geometry', 1, 'قصّ طالب ورقة مربعة طول ضلعها 8 سم ليغطي بها سطحاً. ما مساحة الورقة بالسنتيمتر المربع؟', '["16","32","64","72"]'::jsonb, 2, 'مساحة المربع = الضلع × نفسه = 8 × 8 = 64 سم².') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('kg-02', 'k-geometry', 1, 'أراد طالب تزيين إطار لوحة مربعة طول ضلعها 7 سم بشريط لاصق يحيط بها كاملة. كم سنتيمتراً من الشريط يحتاج؟', '["14","21","28","49"]'::jsonb, 2, 'المطلوب المحيط لا المساحة: محيط المربع = 4 × 7 = 28 سم.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
